// Valida X-Webhook-Secret contra la env var.
const headers = $input.first().json.headers ?? {};
const received =
  headers['x-webhook-secret'] ?? headers['X-Webhook-Secret'];
const expected = $env.WEBHOOK_SECRET;

if (!expected) {
  throw new Error('WEBHOOK_SECRET not set. Restart n8n with ~/start-n8n.sh.');
}
if (!received) {
  throw new Error('Missing X-Webhook-Secret header.');
}
if (received !== expected) {
  throw new Error('Invalid X-Webhook-Secret.');
}

return $input.all();

// Llama directamente a la API de Gemini con fetch nativo y parsea la respuesta.
// Reemplaza 3 nodos (Build body + HTTP Request + Parse) por uno solo más simple.

const pdfText = ($input.first().json.text ?? '').trim();

if (!pdfText) {
  throw new Error(
    'No text extracted from PDF. Probablemente el PDF es escaneado (sin texto seleccionable). El fallback a Vision LLM no está implementado todavía.'
  );
}

const apiKey = $env.GEMINI_API_KEY;
if (!apiKey) {
  throw new Error('GEMINI_API_KEY not set in n8n environment.');
}

const prompt =
  'Sos un asistente experto en menús de restaurantes argentinos. Extraé los datos del siguiente texto y devolvé un JSON con esta estructura exacta:\n\n' +
  '{\n' +
  '  "info": { "name": string, "location": string },\n' +
  '  "menuSections": [{ "id": string (kebab-case), "title": string, "items": [slug,...] }],\n' +
  '  "items": {\n' +
  '    "<slug>": {\n' +
  '      "slug": string (kebab-case ASCII sin acentos),\n' +
  '      "name": string,\n' +
  '      "price": string (solo dígitos, ej \'5500\'),\n' +
  '      "shortDescription": string,\n' +
  '      "icon": string (emoji según categoría),\n' +
  '      "type": string\n' +
  '    }\n' +
  '  }\n' +
  '}\n\n' +
  'Reglas: precios sin $ ni puntos. Slugs kebab-case ASCII sin acentos. Cada slug en menuSections.items debe existir en items{}. Idioma español argentino. Iconos por categoría (pizza:🍕 pasta:🍝 ensalada:🥗 carne:🥩 hamburguesa:🍔 pescado:🐟 postre:🍰 vino:🍷 cerveza:🍺 café:☕ bebida:🥤 sushi:🍣 sopa:🍲 tapa:🍢 vermut:🍹 picada:🧀 sandwich:🥪 fritura:🍟 default:🍽️).\n\n' +
  'Si el texto no es un menú, respondé: {"error":"no_es_menu"}.\n\n' +
  'Respondé SOLO el JSON, sin markdown ni texto extra.\n\n' +
  'Texto del menú:\n\n' +
  pdfText;

const payload = {
  contents: [{ parts: [{ text: prompt }] }],
  generationConfig: {
    responseMimeType: 'application/json',
    temperature: 0.2,
  },
};

const url =
  'https://generativelanguage.googleapis.com/v1beta/models/gemini-2.5-flash:generateContent?key=' +
  apiKey;

let data;
try {
  data = await this.helpers.httpRequest({
    method: 'POST',
    url: url,
    body: payload,
    json: true,
    headers: { 'Content-Type': 'application/json' },
    returnFullResponse: false,
  });
} catch (err) {
  const status = err?.httpCode ?? err?.statusCode ?? '?';
  const body = err?.response?.body ?? err?.message ?? 'unknown';
  throw new Error(
    'Gemini API error ' + status + ': ' + JSON.stringify(body).slice(0, 500)
  );
}

const raw = data?.candidates?.[0]?.content?.parts?.[0]?.text ?? '';

let parsed;
try {
  parsed = JSON.parse(raw);
} catch (err) {
  return [
    {
      json: {
        ok: false,
        error: 'gemini_returned_invalid_json',
        message: err.message,
        rawSample: raw.slice(0, 500),
        pdfCharCount: pdfText.length,
      },
    },
  ];
}

return [
  {
    json: {
      ok: true,
      extracted: parsed,
      pdfCharCount: pdfText.length,
      promptCharCount: prompt.length,
    },
  },
];
